"""Commands added so the product works over the CLI and web app (generated by _tools/add_commands.py)."""

import contextlib
import io
import json
import pathlib
import tempfile
import unittest

from agent_workforce.__main__ import main

EX = pathlib.Path(__file__).resolve().parent.parent / "examples"


class CommandTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, obj) -> str:
        path = pathlib.Path(self.tmp.name) / "req.json"
        path.write_text(json.dumps(obj), encoding="utf-8")
        return str(path)

    def run_cli(self, argv):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = main(argv)
        self.assertIn(code, (0, 1), out.getvalue())
        return json.loads(out.getvalue())

    def test_strong_month_expands_scope(self):
        out = self.run_cli(["review", str(EX / "metrics.json")])
        self.assertEqual(out["action"], "expand_scope")

    def test_incidents_mean_offboard(self):
        m = json.loads((EX / "metrics.json").read_text(encoding="utf-8"))
        m["incidents"] = 2
        self.assertEqual(self.run_cli(["review", self.write(m)])["action"], "offboard")


if __name__ == "__main__":
    unittest.main()
